    if (tot.changed) parts.push(`바뀐 요소 ${tot.changed}`); if (tot.added) parts.push(`새 요소 ${tot.added}`); if (tot.removed) parts.push(`빠진 요소 ${tot.removed}`); if (newPages.length) parts.push(`새 쪽 ${newPages.join(', ')}`);
