    if (tot.replaced) msg += `${msg ? '. ' : ''}공방에서 고친 글 ${tot.replaced}곳은 소식지의 새 내용으로 바꿨습니다(모양은 그대로)`;
    if (tot.kept) msg += `${msg ? '. ' : ''}직접 다듬은 ${tot.kept}곳은 그대로 두었습니다`;
    if (baselined) msg += `${msg ? '. ' : ''}예전에 가져온 쪽 ${baselined}개는 이번에 기준만 잡았습니다(다음 변경부터 반영)`;
