    const mf = t.closest('[data-mfx]'); if (mf) { if (!selAny.length) { toast('먼저 요소를 고르세요 (또는 아래 «차례로 나타나기»)', true); return; } const [k, v] = mf.dataset.mfx.split(':'); applyTo(selAny, k, v); return; }
