    const m = t.match(/^(.*?)\s*\(([^()]*(?:Ctrl|Shift|Space|Home|End|Delete|Esc|[A-Z?←→↑↓=−+])[^()]*)\)\s*$/);
    const keys = m ? m[2].split(/\s*,\s*/).map(g => g.split('+').map(x => `<kbd>${esc(x.trim())}</kbd>`).join('<i>+</i>')).join('<i>,</i>') : '';
