  const nm = window.prompt('내 블록 이름 (요소 패널 → 내 블록에 나옵니다)', els.length === 1 ? (els[0].name || elName(els[0])) : `블록 ${myBlocks.length + 1}`); if (nm == null || !nm.trim()) return;
