  let tq; imeSafe($('#elSearch'), e => { elQ = e.target.value; clearTimeout(tq); tq = setTimeout(() => { if ($('#elSearch') && $('#elSearch')._comp) return; renderElems(); const i = $('#elSearch'); i.focus(); i.setSelectionRange(i.value.length, i.value.length); }, 250); });
