  if (el.locked) h += `<div class="lockbar">🔒 잠긴 요소입니다 — 옮기거나 크기를 바꿀 수 없습니다<button class="btn sm" id="elUnlock">잠금 풀기</button></div>`;
  const geo = `<h3 class="phead"><span>위치·크기 <small>mm</small></span><button class="btn sm" id="elLock" title="Ctrl+L">${el.locked ? '🔓 잠금 풀기' : '🔒 잠그기'}</button></h3><div class="grid4">${F('X', 'x', el.x, { type: 'number', step: 0.5 })}${F('Y', 'y', el.y, { type: 'number', step: 0.5 })}${F('너비', 'w', el.w, { type: 'number', step: 0.5 })}${F('높이', 'h', el.h, { type: 'number', step: 0.5 })}</div>${isPxDoc() ? `<p class="hint" style="margin:2px 0 6px">화면용 문서 — 픽셀로는 위치 ${Math.round(el.x * 96 / 25.4)}, ${Math.round(el.y * 96 / 25.4)} · 크기 ${Math.round(el.w * 96 / 25.4)} × ${Math.round(el.h * 96 / 25.4)}px</p>` : ''}${['image', 'shape', 'path', 'chart'].includes(el.type) ? F('🔗 너비·높이 비율 고정', 'ratioLock', el.ratioLock == null ? el.type === 'image' : el.ratioLock, { type: 'check' }) : ''}${F('회전', 'rot', el.rot || 0, { type: 'angle', def: 0 })}${F('투명도', 'opacity', el.opacity == null ? 1 : el.opacity, { type: 'slider', min: 0, max: 1, step: 0.01, pct: true, def: 1 })}${el.type !== 'text' ? `<div class="pk-lb">겹칠 때 (혼합 모드)</div>${vpick('blend', el.blend || 'normal', ['normal', 'multiply', 'screen', 'overlay', 'darken', 'lighten', 'difference'].map(m => [m, blendIcon(m), '', BLEND_NM[m]]), 'sm')}` : ''}${F('이름', 'name', el.name)}`;
  const shadowBlock = (pfx) => `<details class="fx" ${el.shadow ? 'open' : ''}><summary>${F('그림자', 'shadow', el.shadow, { type: 'check' })}</summary>${F('위치 — 점을 끌어 조정', 'shX,shY', [el.shX == null ? 0.6 : el.shX, el.shY == null ? 0.7 : el.shY], { type: 'xy', range: 4, step: 0.1, presets: [['아래', 0, 1], ['오른쪽 아래', 0.8, 0.8], ['왼쪽 아래', -0.8, 0.8], ['위', 0, -1], ['가운데(번짐만)', 0, 0]] })}
    ${F('번짐', 'shB', el.shB == null ? 0.5 : el.shB, { type: 'slider', min: 0, max: 6, step: 0.1, unit: 'mm', def: 0.5 })}${F('진하기', 'shA', el.shA == null ? 0.3 : el.shA, { type: 'slider', min: 0, max: 1, step: 0.01, pct: true, def: 0.3 })}
    ${F('그림자 색', 'shC', el.shC || '#000000', { type: 'color' })}<div class="pk-lb">빠른 설정</div><div class="pk sm">${[['부드럽게', 0.4, 0.8, 2.2, 0.22], ['또렷하게', 0.6, 0.7, 0.2, 0.45], ['강하게', 1.2, 1.4, 0.6, 0.6], ['떠 있게', 0, 2.2, 3.5, 0.3]].map(([t, x, y, b, a]) => `<button type="button" class="pk-b" data-shq="${x},${y},${b},${a}" title="${t}"><span class="pk-ic"><span class="pk-shd" style="box-shadow:${x * 2.2}px ${y * 2.2}px ${b * 2.4}px rgba(0,0,0,${Math.min(0.9, a * 1.4)})"></span></span><span class="pk-t">${t}</span></button>`).join('')}</div></details>`;
