    if (await confirmBtns(`고른 「${c.name}」 폴더 안에 「나라차디자인공방」 폴더가 있습니다.\n\n확인: 「나라차디자인공방」으로 연결 (권장)\n취소: 고른 「${c.name}」 그대로`)) { await store.useFolder(c.child); c = await store.folderInfo(); }
