  if ([...drv.sel].every(k => { if (k.startsWith('doc:')) { const x = drv.docs[Number(k.slice(4))]; return x && x.path.join('/') === to.join('/'); } const f = drv.folders.find(x => x.name === k.slice(7)); return f && f.path.slice(0, -1).join('/') === to.join('/'); })) return;  /* 제자리 */
