  const B = book(), n = doc.pages.length, pad = (4 - n % 4) % 4;
  const N = (k, t, v, o) => `<label class="f"><span>${t}</span><input type="number" data-bk="${k}" value="${v}" step="${(o && o.step) || 1}" min="${(o && o.min) || 0}"></label>`;
