  if (!loaded) { doc = newDoc(); doc.calendar.year = 2027; doc.name = '2027 인성 캘린더'; virtueTextFix(doc.calendar, 2027); virtueArtFix(doc.calendar, null, 2027); doc.pages = CAL.buildPages(doc, uid, { year: 2027, kind: 'full' }); ensureAllHolidays(); $('#pname').value = doc.name; hist = [snapshot()]; histMeta = [{ cur: 0, sel: [] }]; hptr = 0; renderAll(); setStatus('2027년 캘린더 초안을 만들었습니다. 공휴일은 자동으로 들어갔습니다.'); freshDraft = true; }
  // 동기화 폴더(구글 드라이브): 허락돼 있으면 바로 맞추고, 아니면 한 번 눌러 허락받기
  const nlm0 = /[?&]nlimport=/.test(location.search), acctHash = acctFromHash();
  try {
    const pf = await store.reconnectFolder();
    if (pf === 'none' && store.state.dirSupported && !nlm0 && (!/[?&]qa\b/.test(location.search) || /[?&]acct\b/.test(location.search))) { let seen = ''; try { seen = localStorage.getItem('naracal-acct-guide') || ''; } catch (e) {} if (!seen || acctHash) setTimeout(() => openAcctGuide(true), 900); }
    else if (acctHash) setTimeout(() => openAcctGuide(false), 900);
    if (pf === 'granted') await afterFolderReady();
    else if (pf === 'prompt') {
      $('#status').innerHTML = `<button class="btn sm primary" id="reconnDir">동기화 폴더 "${esc(store.state.dirName)}" 연결 (눌러서 허락)</button>`;
      $('#reconnDir').onclick = async () => { try { if (await store.requestFolderPermission()) { await afterFolderReady({ loadCurrent: true }); updateSaveBadge(); toast('동기화 폴더에 연결했습니다'); } } catch (e) { toast(e.message, true); } };
    }
  } catch (e) { console.warn(e); }
  try { if (store.isDrive()) NC.gdrive.preload(); } catch (e) {}
  updateSaveBadge(); updateToolbarState();
  NC.live.attach({ canSave: () => !!(store.state.handle && !store.state.needPerm), doc: () => doc, state: () => ({ cur, sel, drag: !!drag, dragKind: drag && drag.kind, editing: !!editing || !!$('#cellEd') }), afterRemote: liveAfterRemote, saveSoon: () => { if (store.state.dirty) markDirty(); }, openSettings: openSaveDialog, toast });
  document.fonts && document.fonts.ready.then(() => { fitCache.clear(); renderAll(); });
  /* 11/26 자료실 조: 글꼴이 늦게 도착하면 대체 글꼴 폭으로 맞춘 글이 넘쳤음(「축하합니/다」) — 글꼴이 새로 도착할 때마다 다시 맞춤 */
  if (document.fonts && document.fonts.addEventListener) { let ft = 0; document.fonts.addEventListener('loadingdone', () => { clearTimeout(ft); ft = setTimeout(() => { if (editing || drag) return; fitCache.clear(); try { renderCanvas(); renderOverlay(); } catch (e) {} }, 250); }); }
  /* [11/2] 소식지 프로그램의 [🎨 디자인 공방으로 보내기] — 주소에 nlimport=연-월 이 있으면 그 호를 가져온다(같은 호 디자인이 열려 있으면 내용만 반영) */
  const nlm = /[?&]nlimport=(\d{4}-\d{2})/.exec(location.search);
  if (nlm) { try { history.replaceState(null, '', location.pathname + (location.search.replace(/[?&]nlimport=[^&]*/, '').replace(/^&/, '?') || '')); } catch (e) {} setTimeout(() => newsFromProgram(nlm[1]), 700); }
